#!/usr/bin/env python3
"""Compare generated bytes with the checked-in bytes without changing the checkout."""
from pathlib import Path
import subprocess
import sys

artifacts = {
    'openapi': ('docs/api/openapi.json', 'kansoku-openapi'),
    'contracts': ('docs/contracts/events.json', 'kansoku-contracts'),
}
selected = [sys.argv[1]] if len(sys.argv) > 1 and sys.argv[1] != 'all' else list(artifacts)
failed = False
for name in selected:
    filename, executable = artifacts[name]
    path = Path(filename)
    original = path.read_bytes()
    try:
        subprocess.run(['cabal', 'run', executable], check=True)
        expected = path.read_bytes()
    finally:
        path.write_bytes(original)
    if original != expected:
        print(f'{filename} is stale; run just {name} and review the artifact.', file=sys.stderr)
        failed = True
    else:
        print(f'{filename}: current')
sys.exit(1 if failed else 0)
